262				"benchmarks":         benchmarkClaimViews(claim.benchMap),
263			}
264			rankings = append(rankings, ranking)
265		}
266	
267		out := map[string]any{
268			"claim_type": "fhi_rank",
269			"status":     "ok",
270			"formula":    formulaSnapshot(formula),
271			"ledger":     ledger,
272			"rankings":   rankings,
273		}
274		if len(claims) >= 2 {
275			out["delta"] = roundToOne(claims[0].score - claims[1].score)
276		}
277		out["claim_text"] = buildRankClaimText(claims)
278		return out, nil
279	}
