323	func compareDeltaAxes(formula *fhiFormulaConfig, left, right map[string]any) string {
324		leftBenchmark := benchmarkSnapshot(left)
325		rightBenchmark := benchmarkSnapshot(right)
326		axes := formula.DeltaCoverageAxes
327		if len(axes) == 0 {
328			axes = []string{
329				"benchmark.name",
330				"benchmark.version",
331				"benchmark.dataset_commit",
332				"benchmark.subset_id",
333				"benchmark.subset_version",
334				"benchmark.scorer",
335				"benchmark.scorer_version",
336				"scope.denominator_rule",
337				"coverage.formula_version",
338				"coverage.evidence_window",
339			}
340		}
341		for _, axis := range axes {
342			lv, lok := fhiLookupPath(left, axis)
343			rv, rok := fhiLookupPath(right, axis)
344			if !lok || !rok {
345				return fmt.Sprintf("missing comparison axis %s", axis)
346			}
347			if fmt.Sprint(lv) != fmt.Sprint(rv) {
348				return fmt.Sprintf("comparison axis %s differs: %v vs %v", axis, lv, rv)
349			}
350		}
351		if fhiStringPath(left, "subject.model_raw") != fhiStringPath(right, "subject.model_raw") {
352			return fmt.Sprintf("model differs: %s vs %s", fhiStringPath(left, "subject.model_raw"), fhiStringPath(right, "subject.model_raw"))
353		}
354		if fhiStringPath(left, "subject.provider") != fhiStringPath(right, "subject.provider") {
355			return fmt.Sprintf("provider differs: %s vs %s", fhiStringPath(left, "subject.provider"), fhiStringPath(right, "subject.provider"))
356		}
357		if leftBenchmark["name"] == nil || rightBenchmark["name"] == nil {
358			return "missing benchmark metadata"
359		}
360		return ""
361	}
