497	func groupFHIRecordsBySubject(formula *fhiFormulaConfig, records []map[string]any) map[string]map[string]*benchmarkAggregate {
498		subjects := map[string]map[string]*benchmarkAggregate{}
499		required := make(map[string]struct{}, len(formula.BenchmarkWeights))
500		for _, bench := range formula.BenchmarkWeights {
501			if bench.Weight <= 0 {
502				continue
503			}
504			required[bench.Benchmark] = struct{}{}
505		}
506	
507		for _, record := range records {
508			if !fhiBoolValue(mapValue(record, "denominator")["included"]) {
509				continue
510			}
511			benchName := fhiStringPath(record, "benchmark.name")
512			if _, ok := required[benchName]; !ok {
513				continue
514			}
515			subjectKey := subjectKey(record)
516			if subjectKey == "" {
517				continue
518			}
519			subject := subjects[subjectKey]
520			if subject == nil {
521				subject = map[string]*benchmarkAggregate{}
522				subjects[subjectKey] = subject
523			}
524			agg := subject[benchName]
525			if agg == nil {
526				agg = &benchmarkAggregate{
527					Benchmark: benchmarkSnapshot(record),
528				}
529				subject[benchName] = agg
530			}
531			score, err := normalizedScore(record)
532			if err != nil {
533				continue
534			}
535			agg.Score += score
536			agg.Records = append(agg.Records, record)
537			if rep, ok := fhiIntValue(mapValue(record, "scope")["rep"]); ok {
538				agg.RepIDs = append(agg.RepIDs, rep)
539			}
540			if hash := fhiStringPath(record, "source.artifact_sha256"); hash != "" {
541				agg.SourceHashes = append(agg.SourceHashes, hash)
542			}
543		}
544	
545		for _, subject := range subjects {
546			for _, agg := range subject {
547				if len(agg.Records) > 0 {
548					agg.Score = agg.Score / float64(len(agg.Records))
549				}
550			}
551		}
552		return subjects
553	}
