568	func claimForSubject(group map[string]*benchmarkAggregate, requiredBenchmarks []string, formula *fhiFormulaConfig) (map[string]any, []string, float64, string) {
569		covered := make([]string, 0, len(requiredBenchmarks))
570		benchmarks := map[string]any{}
571		weights := weightMap(formula)
572		var total float64
573		for _, benchName := range requiredBenchmarks {
574			agg, ok := group[benchName]
575			if !ok || agg == nil || len(agg.Records) == 0 {
576				return nil, nil, 0, fmt.Sprintf("missing required benchmark coverage for %s", benchName)
577			}
578			covered = append(covered, benchName)
579			benchmarks[benchName] = benchmarkAggregateView(agg)
580			total += agg.Score * weights[benchName]
581		}
582		subject := selectRepresentativeSubject(group)
583		if subject == nil {
584			return nil, nil, 0, "missing subject details"
585		}
586		view := map[string]any{
587			"record_id":  stringField(subject, "record_id"),
588			"subject":    mapValue(subject, "subject"),
589			"runtime":    mapValue(subject, "runtime"),
590			"provenance": mapValue(subject, "provenance"),
591			"coverage":   mapValue(subject, "coverage"),
592			"benchmarks": benchmarks,
593		}
594		return view, covered, total, ""
595	}
