597	func selectRepresentativeSubject(group map[string]*benchmarkAggregate) map[string]any {
598		keys := make([]string, 0, len(group))
599		for key := range group {
600			keys = append(keys, key)
601		}
602		sort.Strings(keys)
603		var fallback map[string]any
604		for _, key := range keys {
605			agg := group[key]
606			if agg != nil && len(agg.Records) > 0 {
607				for _, record := range agg.Records {
608					if mapValue(record, "runtime") != nil {
609						return record
610					}
611				}
612				if fallback == nil {
613					fallback = agg.Records[0]
614				}
615			}
616		}
617		return fallback
618	}
