648	func weightMap(formula *fhiFormulaConfig) map[string]float64 {
649		out := make(map[string]float64, len(formula.BenchmarkWeights))
650		var total float64
651		for _, bench := range formula.BenchmarkWeights {
652			if bench.Weight <= 0 {
653				continue
654			}
655			out[bench.Benchmark] = bench.Weight
656			total += bench.Weight
657		}
658		if total > 0 {
659			for k, v := range out {
660				out[k] = v / total
661			}
662		}
663		return out
664	}
