666	func summarizeFHILedger(records []map[string]any) map[string]any {
667		invalidByClass := map[string]any{}
668		invalidCount := 0
669		denominatorPolicies := map[string]any{}
670		for _, record := range records {
671			denom := mapValue(record, "denominator")
672			if policy := stringField(denom, "policy"); policy != "" {
673				denominatorPolicies[policy] = intValueAny(denominatorPolicies[policy]) + 1
674			}
675			if !fhiBoolValue(denom["included"]) {
676				invalidCount++
677				class := stringOrEmpty(record, "invalid_class")
678				if class == "" {
679					class = stringField(denom, "policy")
680				}
681				if class == "" {
682					class = "invalid"
683				}
684				invalidByClass[class] = intValueAny(invalidByClass[class]) + 1
685			}
686		}
687		return map[string]any{
688			"record_count":         len(records),
689			"invalid_run_count":    invalidCount,
690			"invalid_run_classes":  invalidByClass,
691			"denominator_policies": denominatorPolicies,
692			"denominator_handling": map[string]any{
693				"policy":           "exclude_invalid_runs",
694				"included_records": len(records) - invalidCount,
695				"excluded_records": invalidCount,
696				"counted_policies": denominatorPolicies,
697			},
698		}
699	}
