701	func buildRankClaimText(claims []fhiSubjectClaim) string {
702		if len(claims) < 2 {
703			return ""
704		}
705		leader := claims[0]
706		runnerUp := claims[1]
707		local := leader
708		frontier := runnerUp
709		if fhiStringPath(frontier.view, "runtime.deployment_class") == "local" || fhiStringPath(frontier.view, "runtime.local_runtime_version") != "" {
710			local, frontier = frontier, local
711		}
712		localModel := firstNonEmptyString(fhiStringPath(local.view, "subject.model_raw"), fhiStringPath(local.view, "subject.model"))
713		localRuntime := firstNonEmptyString(fhiStringPath(local.view, "runtime.local_runtime_name"), fhiStringPath(local.view, "subject.provider"))
714		localRuntimeVersion := firstNonEmptyString(fhiStringPath(local.view, "runtime.local_runtime_version"), fhiStringPath(local.view, "provenance.provider_version"))
715		frontierModel := firstNonEmptyString(fhiStringPath(frontier.view, "subject.model_raw"), fhiStringPath(frontier.view, "subject.model"))
716		return fmt.Sprintf("With fiz %s and %s %s, %s gets FHI %.0f, %.0f points behind %s.",
717			fhiStringPath(local.view, "provenance.fizeau_version"),
718			localRuntime, localRuntimeVersion,
719			localModel, roundToOne(local.score), abs(roundToOne(frontier.score-local.score)),
720			frontierModel,
721		)
722	}
