733	func uniqueStrings(values []string) []string {
734		seen := make(map[string]struct{}, len(values))
735		out := make([]string, 0, len(values))
736		for _, value := range values {
737			if strings.TrimSpace(value) == "" {
738				continue
739			}
740			if _, ok := seen[value]; ok {
741				continue
742			}
743			seen[value] = struct{}{}
744			out = append(out, value)
745		}
