797	func fhiFloatValue(v any) (float64, bool) {
798		switch n := v.(type) {
799		case float64:
800			return n, true
801		case int:
802			return float64(n), true
803		case int64:
804			return float64(n), true
805		case json.Number:
806			out, err := n.Float64()
807			if err != nil {
808				return 0, false
809			}
810			return out, true
811		default:
812			return 0, false
813		}
