816	func fhiLookupPath(doc map[string]any, path string) (any, bool) {
817		var cur any = doc
818		for _, segment := range strings.Split(path, ".") {
819			m, ok := cur.(map[string]any)
820			if !ok {
821				return nil, false
822			}
823			next, ok := m[segment]
824			if !ok {
825				return nil, false
826			}
827			cur = next
828		}
829		return cur, true
830	}
