107	func assertStringPath(t *testing.T, doc map[string]any, path, want string) {
108		t.Helper()
109	
110		got, ok := lookupAnyPath(doc, path)
111		if !ok {
112			t.Fatalf("missing %s", path)
113		}
114		str, ok := got.(string)
115		if !ok {
116			t.Fatalf("%s = %T, want string", path, got)
117		}
118		if str != want {
119			t.Fatalf("%s = %q, want %q", path, str, want)
120		}
121	}
