123	func assertNumberPath(t *testing.T, doc map[string]any, path string, want float64) {
124		t.Helper()
125	
126		got, ok := lookupAnyPath(doc, path)
127		if !ok {
128			t.Fatalf("missing %s", path)
129		}
130		var gotFloat float64
131		switch v := got.(type) {
132		case float64:
133			gotFloat = v
134		case int:
135			gotFloat = float64(v)
136		case int64:
137			gotFloat = float64(v)
138		default:
139			t.Fatalf("%s = %T, want numeric", path, got)
140		}
141		if gotFloat != want {
142			t.Fatalf("%s = %v, want %v", path, gotFloat, want)
143		}
144	}
