160	func lookupAnyPath(value any, path string) (any, bool) {
161		cur := value
162		for _, segment := range strings.Split(path, ".") {
163			switch node := cur.(type) {
164			case map[string]any:
165				next, ok := node[segment]
166				if !ok {
167					return nil, false
168				}
169				cur = next
170			default:
171				rv := reflect.ValueOf(cur)
172				if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
173					idx, ok := parseIndex(segment)
174					if !ok || idx < 0 || idx >= rv.Len() {
175						return nil, false
176					}
177					cur = rv.Index(idx).Interface()
178					continue
179				}
180				return nil, false
181			}
182		}
183		return cur, true
184	}
185	
186	func parseIndex(segment string) (int, bool) {
187		var idx int
188		for _, r := range segment {
189			if r < '0' || r > '9' {
190				return 0, false
191			}
192			idx = idx*10 + int(r-'0')
193		}
194		return idx, true
195	}
